<section class="play__body" data-version="<%= @revision %>" data-ended="<%= @game.phase == 'ended' %>">
  <% if @game.phase == 'ended' %>
    <h1 class="play-title">The quiz is over</h1>
  <% elsif !@player %>
    <h1 class="play-title">Join the quiz</h1>
    <% if @error %><p role="alert"><%= @error %></p><% end %>
    <%= form_with url: join_play_path(@game.code), class: 'join-form' do |f| %>
      <%= f.label :name, 'Your name' %><%= f.text_field :name, required: true, maxlength: 100, autocomplete: 'nickname', class: 'input' %>
      <%= f.submit 'Join', class: 'btn' %>
    <% end %>
  <% elsif @game.phase == 'lobby' %>
    <div class="waiting"><span class="waiting__gem" aria-hidden="true">?</span>
      <h1 class="play-title">Hi, <%= @player.name %>!</h1>
      <p class="play-lead">Waiting for the quiz to start…</p>
    </div>
  <% else %>
    <div class="play-question__num">Question <%= @round.number %> of <%= @game.round_count %></div>
    <h1 class="play-question__body"><%= @round.body %></h1>
    <% if @game.phase == 'open' %>
      <div class="play-options">
        <% lettered(@round.options).each_with_index do |(option, letter), i| %>
          <%= button_to answer_play_path(@game.code), params: { number: @round.number, choice: i }, class: "play-option #{'is-picked' if @choice == i}", aria: { pressed: @choice == i } do %>
            <span class="play-option__letter" aria-hidden="true"><%= letter %></span><span class="play-option__title"><%= option['text'] %></span>
            <% if @choice == i %><span class="play-option__mark">Your answer</span><% end %>
          <% end %>
        <% end %>
      </div>
    <% else %>
      <p class="play-status" role="status"><%= @choice.nil? ? 'No answer' : (@round.options.fetch(@choice)['correct'] ? 'Correct!' : 'Wrong!') %></p>
    <% end %>
  <% end %>
</section>
ERB
cat > app/assets/javascripts/live.js <<'JS'
// Serialize state reads and writes. On slow connections an old poll must not
// overwrite a submitted answer, nor should rapid taps arrive out of order.
let screen = document.querySelector('[data-version]');
const notice = document.querySelector('#live-error');
let queue = Promise.resolve();
let timer;
let failures = 0;

function schedule() {
  clearTimeout(timer);
  if (screen.dataset.ended === 'true') return;
  const delay = Math.min(15000, 1050 * 2 ** failures) + Math.random() * 400;
  timer = setTimeout(() => enqueue(), delay);
}

function enqueue(post) {
  clearTimeout(timer);
  queue = queue.then(async () => {
    const headers = { 'X-Live-Screen': '1' };
    if (!post) headers['X-Screen-Version'] = screen.dataset.version;
    const response = await fetch(post?.url || location.pathname, {
      headers, method: post ? 'POST' : 'GET', body: post?.body,
      cache: 'no-store', signal: AbortSignal.timeout(10000)
    });
    if (!response.ok) throw new Error('Request failed');
    if (response.status !== 204) {
      const template = document.createElement('template');
      template.innerHTML = await response.text();
      const next = template.content.querySelector('[data-version]');
      if (!next) throw new Error('Missing screen');
      screen.replaceWith(next);
      screen = next;
    }
    failures = 0;
    notice.hidden = true;
  }).catch(() => {
    failures++;
    notice.textContent = post ? 'Could not confirm that action. Check the screen and try again.' : 'Reconnecting…';
    notice.hidden = false;
  }).finally(schedule);
}

document.addEventListener('submit', event => {
  if (!screen.contains(event.target)) return;
  event.preventDefault();
  enqueue({ url: new URL(event.target.action).pathname, body: new FormData(event.target) });
});
window.addEventListener('online', () => enqueue());
document.addEventListener('visibilitychange', () => { if (!document.hidden) enqueue(); });
schedule();
JS
